-- CHAMBA 041 — Paneles admin/cliente sin depender de JWT (login teléfono / piloto)SET statement_timeout = '120s';-- ── Admin: torre de control (jobs + asignaciones) ───────────────────────────CREATE OR REPLACE FUNCTION DROP FUNCTION IF EXISTS get_admin_control_jobs CASCADE;CREATE OR REPLACE FUNCTION get_admin_control_jobs(p_admin_id UUID)RETURNS JSONBLANGUAGE plpgsqlSECURITY DEFINERSET search_path = publicAS $$BEGIN  IF p_admin_id IS NULL THEN    RETURN '[]'::jsonb;  END IF;  IF NOT EXISTS (    SELECT 1 FROM profiles p    WHERE p.id = p_admin_id AND p.role::text = 'admin'  ) THEN    RETURN '[]'::jsonb;  END IF;  RETURN COALESCE((    SELECT jsonb_agg(job_row ORDER BY job_row->>'created_at' DESC)    FROM (      SELECT jsonb_build_object(        'id', j.id,        'title', j.title,        'description', j.description,        'category', j.category,        'status', j.status,        'operational_phase', j.operational_phase,        'pay_amount', j.pay_amount,        'worker_payout', j.worker_payout,        'platform_fee', j.platform_fee,        'duration_hours', j.duration_hours,        'address', j.address,        'lat', j.lat,        'lng', j.lng,        'scheduled_at', j.scheduled_at,        'scheduled_date', j.scheduled_date,        'scheduled_time', j.scheduled_time,        'urgency_level', j.urgency_level,        'required_workers', j.required_workers,        'slots_taken', j.slots_taken,        'media_urls', j.media_urls,        'created_by', j.created_by,        'assigned_worker_id', j.assigned_worker_id,        'created_at', j.created_at,        'updated_at', j.updated_at,        'moderated_by', j.moderated_by,        'moderation_reason', j.moderation_reason,        'moderated_at', j.moderated_at,        'creator', (          SELECT jsonb_build_object('id', c.id, 'full_name', c.full_name)          FROM profiles c WHERE c.id = j.created_by        ),        'assignments', COALESCE((          SELECT jsonb_agg(            jsonb_build_object(              'id', ja.id,              'worker_id', ja.worker_id,              'assigned_at', ja.assigned_at,              'completed_at', ja.completed_at,              'payment_status', ja.payment_status,              'worker', (                SELECT jsonb_build_object(                  'id', w.id,                  'full_name', w.full_name,                  'phone', w.phone,                  'avatar_url', w.avatar_url                )                FROM profiles w WHERE w.id = ja.worker_id              )            )          )          FROM job_assignments ja          WHERE ja.job_id = j.id        ), '[]'::jsonb)      ) AS job_row      FROM jobs j    ) sub  ), '[]'::jsonb);END;$$;GRANT EXECUTE ON FUNCTION get_admin_control_jobs(UUID) TO anon, authenticated;-- ── Cliente: mis solicitudes con técnico asignado ───────────────────────────CREATE OR REPLACE FUNCTION DROP FUNCTION IF EXISTS get_client_orders_panel CASCADE;CREATE OR REPLACE FUNCTION get_client_orders_panel(p_client_id UUID)RETURNS JSONBLANGUAGE sqlSECURITY DEFINERSET search_path = publicAS $$  SELECT COALESCE(    jsonb_agg(row_to_json(x)::jsonb ORDER BY x.created_at DESC),    '[]'::jsonb  )  FROM (    SELECT      j.*,      CASE WHEN w.id IS NULL THEN NULL ELSE jsonb_build_object(        'id', w.id,        'full_name', w.full_name,        'avatar_url', w.avatar_url,        'phone', w.phone      ) END AS assigned_worker    FROM jobs j    LEFT JOIN profiles w ON w.id = j.assigned_worker_id    WHERE j.created_by = p_client_id  ) x;$$;GRANT EXECUTE ON FUNCTION get_client_orders_panel(UUID) TO anon, authenticated;